import React, { useMemo, useState } from "react";

export type GFormOption = {
  label: string;
  value: string;
};

export type GFormField = {
  name: string;
  type?: string;
  label?: string;
  placeholder?: string;
  required?: boolean;
  defaultValue?: unknown;
  options?: GFormOption[];
  rows?: number;
  [key: string]: unknown;
};

export type GFormTemplate = {
  layout: {
    width: string | number;
    maxWidth: string | number;
    columns: number;
    borderRadius: string | number;
    inputRadius: string | number;
    buttonRadius: string | number;
    textareaRows: number;
  };
  typography: {
    fontFamily: string;
    labelSize: string | number;
    labelWeight: string | number;
    inputSize: string | number;
    buttonSize: string | number;
    buttonWeight: string | number;
  };
  spacing: {
    formPadding: string | number;
    fieldGap: string | number;
    labelGap: string | number;
    inputPaddingX: string | number;
    inputPaddingY: string | number;
    buttonPaddingX: string | number;
    buttonPaddingY: string | number;
  };
  color: {
    background: string;
    fieldBackground: string;
    text: string;
    mutedText: string;
    border: string;
    primary: string;
    primaryHover: string;
    primaryText: string;
    error: string;
    focus: string;
  };
};

export type GFormTemplateOverride = {
  layout?: Partial<GFormTemplate["layout"]>;
  typography?: Partial<GFormTemplate["typography"]>;
  spacing?: Partial<GFormTemplate["spacing"]>;
  color?: Partial<GFormTemplate["color"]>;
};

type Props = {
  fields: GFormField[];
  template: GFormTemplate;
  overrides?: GFormTemplateOverride;
  submitLabel?: string;
  submittingLabel?: string;
  onSubmit: (values: Record<string, unknown>) => Promise<void> | void;
};

const unit = (value: string | number) =>
  typeof value === "number" ? `${value}px` : value;

export default function GForm({
  fields,
  template,
  overrides = {},
  submitLabel = "Submit",
  submittingLabel = "Sending...",
  onSubmit,
}: Props) {
  const visual = {
    layout: { ...template.layout, ...overrides.layout },
    typography: { ...template.typography, ...overrides.typography },
    spacing: { ...template.spacing, ...overrides.spacing },
    color: { ...template.color, ...overrides.color },
  };

  const initialValues = useMemo(
    () =>
      Object.fromEntries(
        fields.map((field) => [
          field.name,
          // A checkbox group holds several answers, so it starts as an array
          // rather than the empty string every other field starts as.
          field.defaultValue ?? (field.type === "checkbox" ? [] : ""),
        ])
      ),
    [fields]
  );

  const [values, setValues] = useState<Record<string, unknown>>(initialValues);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");
  const [hovered, setHovered] = useState(false);
  const [focused, setFocused] = useState<string | null>(null);

  const setValue = (name: string, value: unknown) => {
    setValues((current) => ({ ...current, [name]: value }));
  };

  /** Adds or removes one option from a checkbox group's array of answers. */
  const toggleValue = (name: string, option: string, checked: boolean) => {
    setValues((current) => {
      const existing = Array.isArray(current[name]) ? (current[name] as string[]) : [];
      const next = checked
        ? existing.includes(option)
          ? existing
          : [...existing, option]
        : existing.filter((value) => value !== option);

      return { ...current, [name]: next };
    });
  };

  const submit: React.FormEventHandler<HTMLFormElement> = async (event) => {
    event.preventDefault();
    if (loading) return;

    setLoading(true);
    setError("");

    try {
      await onSubmit(values);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Unable to submit form.");
    } finally {
      setLoading(false);
    }
  };

  const inputStyle = (fieldName: string): React.CSSProperties => ({
    width: "100%",
    boxSizing: "border-box",
    fontFamily: visual.typography.fontFamily,
    fontSize: unit(visual.typography.inputSize),
    color: visual.color.text,
    background: visual.color.fieldBackground,
    border: `1px solid ${focused === fieldName ? visual.color.focus : visual.color.border}`,
    borderRadius: unit(visual.layout.inputRadius),
    padding: `${unit(visual.spacing.inputPaddingY)} ${unit(visual.spacing.inputPaddingX)}`,
    outline: "none",
    transition: "border-color 160ms ease, box-shadow 160ms ease",
    boxShadow:
      focused === fieldName ? `0 0 0 3px ${visual.color.focus}22` : "none",
  });

  return (
    <form
      onSubmit={submit}
      style={{
        width: visual.layout.width,
        maxWidth: visual.layout.maxWidth,
        boxSizing: "border-box",
        padding: unit(visual.spacing.formPadding),
        //border: `1px solid ${visual.color.border}`,
        borderRadius: unit(visual.layout.borderRadius),
        background: visual.color.background,
        color: visual.color.text,
        fontFamily: visual.typography.fontFamily,
      }}
    >
      <div
        style={{
          display: "grid",
          gridTemplateColumns: `repeat(${visual.layout.columns}, minmax(0, 1fr))`,
          gap: unit(visual.spacing.fieldGap),
        }}
      >
        {fields.map((field) => {
          const type = field.type ?? "text";
          const raw = values[field.name];
          /* Checkbox groups keep an array; everything else is a single string.
             Coercing the array here would render it as "a,b" in an input. */
          const selected = Array.isArray(raw) ? (raw as string[]) : [];
          const value = raw === undefined || raw === null || Array.isArray(raw)
            ? ""
            : String(raw);
          const isGroup = type === "radio" || type === "checkbox";

          return (
            <div
              key={field.name}
              style={{
                minWidth: 0,
                gridColumn:
                  type === "textarea" && visual.layout.columns > 1
                    ? "1 / -1"
                    : undefined,
              }}
            >
              {field.label && type !== "hidden" && !isGroup && (
                <label
                  htmlFor={field.name}
                  style={{
                    display: "block",
                    marginBottom: unit(visual.spacing.labelGap),
                    fontSize: unit(visual.typography.labelSize),
                    fontWeight: visual.typography.labelWeight,
                    color: visual.color.text,
                  }}
                >
                  {field.label}
                </label>
              )}

              {isGroup ? (
                /* A group of choices is a fieldset with a legend, not a label
                   pointing at one input: that is what lets a screen reader
                   announce the question before each option, and what makes
                   arrow keys move within a radio group natively. */
                <fieldset
                  style={{
                    margin: 0,
                    padding: 0,
                    border: 0,
                    minWidth: 0,
                  }}
                >
                  {field.label && (
                    <legend
                      style={{
                        padding: 0,
                        marginBottom: unit(visual.spacing.labelGap),
                        fontSize: unit(visual.typography.labelSize),
                        fontWeight: visual.typography.labelWeight,
                        color: visual.color.text,
                      }}
                    >
                      {field.label}
                    </legend>
                  )}

                  <div style={{ display: "grid", gap: 8 }}>
                    {(field.options ?? []).map((option) => {
                      const id = `${field.name}-${option.value}`;
                      const checked =
                        type === "checkbox"
                          ? selected.includes(option.value)
                          : value === option.value;

                      return (
                        <label
                          key={option.value}
                          htmlFor={id}
                          style={{
                            display: "flex",
                            alignItems: "center",
                            gap: 10,
                            fontSize: unit(visual.typography.inputSize),
                            color: visual.color.text,
                            cursor: "pointer",
                          }}
                        >
                          <input
                            id={id}
                            type={type}
                            name={field.name}
                            value={option.value}
                            checked={checked}
                            /* On a radio group `required` belongs on every
                               input, which is how the browser validates that
                               one of them was chosen. A checkbox group cannot
                               express "at least one" natively, so it is not
                               marked required at all rather than making every
                               box individually mandatory. */
                            required={type === "radio" ? field.required : undefined}
                            style={{
                              width: 17,
                              height: 17,
                              margin: 0,
                              accentColor: visual.color.primary,
                              flexShrink: 0,
                            }}
                            onFocus={() => setFocused(field.name)}
                            onBlur={() => setFocused(null)}
                            onChange={(event) =>
                              type === "checkbox"
                                ? toggleValue(
                                    field.name,
                                    option.value,
                                    event.target.checked
                                  )
                                : setValue(field.name, option.value)
                            }
                          />
                          {option.label}
                        </label>
                      );
                    })}
                  </div>
                </fieldset>
              ) : type === "textarea" ? (
                <textarea
                  id={field.name}
                  name={field.name}
                  rows={field.rows ?? visual.layout.textareaRows}
                  placeholder={field.placeholder}
                  required={field.required}
                  value={value}
                  style={{ ...inputStyle(field.name), resize: "vertical" }}
                  onFocus={() => setFocused(field.name)}
                  onBlur={() => setFocused(null)}
                  onChange={(event) => setValue(field.name, event.target.value)}
                />
              ) : type === "select" ? (
                <select
                  id={field.name}
                  name={field.name}
                  required={field.required}
                  value={value}
                  style={inputStyle(field.name)}
                  onFocus={() => setFocused(field.name)}
                  onBlur={() => setFocused(null)}
                  onChange={(event) => setValue(field.name, event.target.value)}
                >
                  {field.placeholder && (
                    <option value="">{field.placeholder}</option>
                  )}
                  {(field.options ?? []).map((option) => (
                    <option key={option.value} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </select>
              ) : (
                <input
                  id={field.name}
                  name={field.name}
                  type={type}
                  placeholder={field.placeholder}
                  required={field.required}
                  /* A count of years or occupants has no negative answer, and
                     the spinner would happily offer one. Only applied to
                     number fields, so every other input is untouched. */
                  min={type === "number" ? 0 : undefined}
                  inputMode={type === "number" ? "numeric" : undefined}
                  value={value}
                  style={inputStyle(field.name)}
                  onFocus={() => setFocused(field.name)}
                  onBlur={() => setFocused(null)}
                  onChange={(event) => setValue(field.name, event.target.value)}
                />
              )}
            </div>
          );
        })}
      </div>

      {error && (
        <div
          role="alert"
          style={{
            marginTop: unit(visual.spacing.fieldGap),
            color: visual.color.error,
            fontSize: unit(visual.typography.labelSize),
          }}
        >
          {error}
        </div>
      )}

      <button
        type="submit"
        disabled={loading}
        onMouseEnter={() => setHovered(true)}
        onMouseLeave={() => setHovered(false)}
        style={{
          width: "100%",
          marginTop: unit(visual.spacing.fieldGap),
          padding: `${unit(visual.spacing.buttonPaddingY)} ${unit(visual.spacing.buttonPaddingX)}`,
          border: 0,
          borderRadius: unit(visual.layout.buttonRadius),
          background:
            hovered && !loading
              ? visual.color.primaryHover
              : visual.color.primary,
          color: visual.color.primaryText,
          fontFamily: visual.typography.fontFamily,
          fontSize: unit(visual.typography.buttonSize),
          fontWeight: visual.typography.buttonWeight,
          cursor: loading ? "wait" : "pointer",
          opacity: loading ? 0.7 : 1,
          transition: "background 160ms ease, transform 160ms ease",
          transform: hovered && !loading ? "translateY(-1px)" : "none",
        }}
      >
        {loading ? submittingLabel : submitLabel}
      </button>
    </form>
  );
}
