// Form submissions, in Supabase.
//
// This replaces a pipeline that has never worked on this site: the public
// forms encrypt every answer with an RSA public key and post it to a Google
// Form, which lands in a GitHub repository, which the CMS decrypts in the
// browser. Sold by Sajra has neither the form id nor the keypair, so both
// public forms currently refuse to submit.
//
// Here a submission is one row in `leads`. Row Level Security does the work
// the encryption was doing: anyone may INSERT — the whole point of a public
// enquiry form — and only a signed-in user may SELECT. An anon key found in
// the page source can post an enquiry and cannot read one back.
//
// ── what this gives up, stated plainly ───────────────────────────────────
// The RSA design meant the host could not read submissions even in principle.
// This one means Supabase can, the same way any hosted database can. That is
// the trade Nate asked for — "a temporary quick and dirty solution" — and it
// is the normal arrangement for a contact form, but it IS a change and the
// client should know about it rather than discover it.

import { supabaseRequest } from "./client.ts";
import type { SupabaseResult } from "./client";
import { normalizeLead } from "../gh-leads/normalizeLead.ts";
import type { Lead } from "../gh-leads/types";
import type { Submission } from "../gforms/buildSubmission";

const TABLE = "/rest/v1/leads";

/** One row of `leads`, as the schema defines it. */
export type LeadRow = {
  id: string;
  created_at: string;
  name: string;
  phone: string;
  email: string;
  message: string;
  site_id: string;
  form_id: string | null;
  form_name: string | null;
  /** Every answer the form collected, as submitted. */
  answers: Record<string, unknown>;
  /**
   * Set while the lead is in the Trash. Null is the normal state.
   *
   * Optional as well as nullable: a submission being inserted does not carry
   * it at all — the column defaults to null in the database — so requiring it
   * would force every public form to send a field about CMS housekeeping.
   */
  deleted_at?: string | null;
  /**
   * "application" or "enquiry", as the form that produced it declared.
   *
   * Null on rows received before MTC-KRP-047, which is why the Leads view
   * falls back to deriving it rather than showing those as unknown.
   */
  kind?: string | null;
};

/**
 * Stores one submission.
 *
 * Unauthenticated on purpose: this runs for a visitor filling in the contact
 * form, who has no account and never will. The `anon` INSERT policy in
 * schema.sql is what makes it work, and the absence of an anon SELECT policy
 * is what stops the same key reading everybody else's enquiry.
 */
export function leadRowFrom(submission: Submission): Omit<LeadRow, "created_at"> {
  return {
    id: submission.submissionId,
    name: submission.name,
    phone: submission.phone,
    email: submission.email,
    message: submission.message,
    site_id: submission.siteId,
    form_id: submission.form?.id ?? null,
    form_name: submission.form?.name ?? null,
    kind: submission.form?.kind ?? null,
    /* Every answer, including questions an editor added yesterday. A fixed
       column per field would have dropped those silently. */
    answers: submission.answers,
  };
}

export async function submitLead(
  submission: Submission
): Promise<SupabaseResult<null>> {
  const row = leadRowFrom(submission);

  const result = await supabaseRequest<unknown>(TABLE, {
    method: "POST",
    headers: { Prefer: "return=minimal" },
    body: [row],
    authenticated: false,
  });

  if (!result.ok) return result;
  return { ok: true, data: null };
}

/**
 * Every submission, newest first — trashed ones included.
 *
 * The Trash tab needs them, and filtering live from deleted is the view own
 * job (modules/shared/trash.ts). Fetching both in one request also means the
 * two tabs can never disagree about how many there are.
 *
 * Authenticated, so this returns nothing at all to a signed-out browser —
 * which is the security boundary, not a UI decision.
 */
export async function fetchLeadRows(): Promise<SupabaseResult<Lead[]>> {
  const result = await supabaseRequest<LeadRow[]>(
    `${TABLE}?select=*&order=created_at.desc`,
    { method: "GET" }
  );

  if (!result.ok) return result;

  const rows = Array.isArray(result.data) ? result.data : [];

  return { ok: true, data: rows.map(toLead) };
}

/**
 * One row as the Leads table renders it.
 *
 * Routed through `normalizeLead` rather than hand-mapped, so a row and a
 * decrypted GitHub submission produce the same Lead and the table, the popout
 * and the quick actions keep working unchanged. The filename argument is where
 * that function reads the timestamp from, so the row's `created_at` is handed
 * over in the shape it expects.
 */
export function toLead(row: LeadRow): Lead {
  const receivedAt = Date.parse(row.created_at);

  const lead = normalizeLead(
    `${Number.isFinite(receivedAt) ? receivedAt : 0}.json`,
    {
      submissionId: row.id,
      name: row.name,
      phone: row.phone,
      email: row.email,
      message: row.message,
      siteId: row.site_id,
      form: row.form_id ?? row.form_name ?? "",
    }
  );

  /* Carried separately: normalizeLead describes what the applicant sent, and
     these are recorded alongside it rather than being part of it. */
  if (row.kind === "application" || row.kind === "enquiry") lead.kind = row.kind;
  if (row.deleted_at) lead.deletedAt = row.deleted_at;

  return lead;
}

/**
 * Moves leads to the Trash, or restores them when `deletedAt` is null.
 *
 * One request for the whole selection rather than one per lead: deleting four
 * leads should either happen or not, and four separate calls can leave two
 * deleted and two not with nothing to tell the user which.
 */
export async function setLeadsDeleted(
  ids: string[],
  deletedAt: string | null
): Promise<SupabaseResult<null>> {
  if (ids.length === 0) return { ok: true, data: null };

  const list = ids.map((id) => `"${encodeURIComponent(id)}"`).join(",");

  const result = await supabaseRequest<unknown>(`${TABLE}?id=in.(${list})`, {
    method: "PATCH",
    headers: { Prefer: "return=minimal" },
    body: { deleted_at: deletedAt },
  });

  if (!result.ok) return result;
  return { ok: true, data: null };
}
